document:
mutation CallAccept($input: CallAcceptInput!) {
  callAccept(input: $input) {
    call {
      id
      status
      answeredAt
      endedAt
    }
    iceServers {
      urls
      username
      credential
    }
  }
}

mutation CallDecline($input: CallDeclineInput!) {
  callDecline(input: $input) {
    call {
      id
      status
      answeredAt
      endedAt
    }
  }
}

mutation CallEnd($input: CallEndInput!) {
  callEnd(input: $input) {
    call {
      id
      status
      answeredAt
      endedAt
    }
  }
}

mutation CallSignalSend($input: CallSignalSendInput!) {
  callSignalSend(input: $input) {
    call {
      id
      status
    }
  }
}

mutation CallStart($input: CallStartInput!) {
  callStart(input: $input) {
    call {
      id
      status
      mediaKind
      origin
      peer {
        id
      }
      direction
      createdAt
      answeredAt
      endedAt
    }
    iceServers {
      urls
      username
      credential
    }
  }
}

mutation CampaignRedeem($input: CampaignRedeemInput!) {
  campaignRedeem(input: $input) {
    wallet {
      ...WalletFragment
    }
  }
}

fragment WalletFragment on Wallet {
  balance
  premium {
    id
    expiresAt
    createdAt
    updatedAt
    product {
      productId
    }
  }
}

mutation CampaignSkip($input: CampaignSkipInput!) {
  campaignSkip(input: $input) {
    status
  }
}

mutation ChatActionSet($input: ChatActivitySetInput!) {
  chatActivitySet(input: $input) {
    chat {
      id
    }
  }
}

mutation ChatGroupCreate($input: GroupChatCreateInput!) {
  groupChatCreate(input: $input) {
    skippedUserIds
    chat {
      ...ChatFragment
    }
  }
}

fragment ChatFragment on Chat {
  id
  uuid
  kind
  name
  logoUrl
  description
  messagesCount
  membersCount
  lastActivityAt
  lastMessageAt
  connectedAt
  createdAt
  updatedAt
  ownerId
  revision
  viewerState {
    list
    lists
    connectionStatus
    premium
    pinned
    muted
    mutedUntil
    read
    unreadCount
    readMarks {
      ...ReadMarksFragment
    }
  }
  opponent {
    ...UserStandardFragment
  }
  summary {
    id
    body
    languageCode
    generatedAt
  }
  lastMessage {
    ...LastMessageFragment
  }
}

fragment ReadMarksFragment on ReadMarks {
  total
  read
  unread
  readByViewer
  latestReadAt
  members {
    userId
    readAt
  }
}

fragment UserStandardFragment on User {
  id
  fullName
  username
  avatarUrl
  online
  lastSeenAt
  age
  distance
  description
  story
  createdAt
  updatedAt
  country {
    name
  }
  relationship {
    ...RelationshipFragment
  }
}

fragment RelationshipFragment on UserRelationship {
  status
  chatId
  lastInteraction
}

fragment LastMessageFragment on Message {
  id
  updatedAt
  ...MessageFragment
}

fragment MessageFragment on Message {
  id
  body
  kind
  status
  createdAt
  updatedAt
  modifiedAt
  chatId
  oneTime
  expired
  expiresAt
  isSystem
  systemKind
  isForwarded
  isReply
  unread
  sequenceNumber
  mediaGroup {
    id
    position
    size
  }
  transcribed
  transcript
  transcriptLanguage
  readCount
  prompt {
    id
    text
    translations {
      locale
      text
    }
  }
  author {
    ...UserMinimalFragment
  }
  forwardedFrom {
    id
  }
  media {
    ...MediaFragment
  }
  attachment {
    __typename
    ... on MomentAttachment {
      ...AttachedMomentUserFragment
      reaction {
        id
        body
        createdAt
        updatedAt
        user {
          ...UserMinimalFragment
        }
      }
    }
    ... on GiftAttachment {
      id
      giftTier: kind
      status
      createdAt
      updatedAt
      gift {
        ...GiftFragment
      }
      moment {
        ...AttachedMomentUserFragment
      }
    }
    ... on ProfileAttachment {
      user {
        id
        fullName
        username
        avatarUrl
      }
    }
    ... on ReactionAttachment {
      id
      body
      createdAt
      updatedAt
      user {
        ...UserMinimalFragment
      }
    }
  }
  location {
    ...LocationFragment
  }
  replyTo {
    id
    body
    kind
    createdAt
    status
    chatId
    oneTime
    isSystem
    replyTo {
      id
    }
    forwardedFrom {
      id
    }
    prompt {
      id
      text
      translations {
        locale
        text
      }
    }
    author {
      ...UserMinimalFragment
    }
    media {
      ...MediaFragment
    }
  }
  reactions {
    ...ReactionFragment
  }
  mentions {
    id
    username
  }
}

fragment UserMinimalFragment on User {
  id
  fullName
  username
  avatarUrl
  online
  lastSeenAt
  createdAt
  updatedAt
  relationship {
    ...RelationshipFragment
  }
}

fragment MediaFragment on MessageMedia {
  blobId
  blurHash
  coverUrl
  createdAt
  duration
  fileUrl
  gifUrl
  height
  kind
  thumbUrl
  transcoded
  transcodeStatus
  transcodeProgress
  transcodeError
  updatedAt
  width
}

fragment AttachedMomentUserFragment on MomentAttachment {
  id
  uuid
  momentKind: kind
  contentKind
  createdAt
  updatedAt
  user {
    id
    fullName
    createdAt
    updatedAt
  }
  media {
    ...MediaFragment
  }
  widgets {
    ...MomentWidgetFragment
  }
}

fragment MomentWidgetFragment on MomentWidget {
  createdAt
  id
  kind
  updatedAt
  settings {
    offset {
      x
      y
    }
    scale
    rotate
    itemProps {
      __typename
      ... on MomentLabelProps {
        title
        color
        backgroundColor
        fontFamily
        textAlign
      }
      ... on MomentEmojiProps {
        emoji
      }
      ... on MomentGifProps {
        gifId
        url
      }
      ... on MomentLocationProps {
        location {
          id
          name
          coord
        }
        colorIndex
      }
      ... on MomentHashtagProps {
        title
        colorIndex
      }
      ... on MomentTemperatureProps {
        value
      }
    }
  }
}

fragment GiftFragment on Gift {
  animationUrl
  cost
  createdAt
  description
  id
  imageUrl
  name
  price
  status
  updatedAt
}

fragment LocationFragment on UserLocation {
  address
  city
  lat
  lng
  name
}

fragment ReactionFragment on MessageReaction {
  id
  body
  createdAt
  updatedAt
  user {
    ...UserMinimalFragment
  }
}

mutation ChatGroupCreateFile($name: String!, $userIds: [ID!]!, $signedId: String!) {
