query userMoments($userId: ID!, $first: Int, $after: Cursor) {
  user(id: $userId) {
    moments(first: $first, after: $after) {
      edges {
        cursor
        impressionScore
        impressionUuid
        node {
          ...MomentCardFragment
          visitors(first: 3, order: ID_DESC) {
            edges {
              node {
                ...UserStandardFragment
              }
            }
          }
        }
      }
      pageInfo {
        ...PageInfoFragment
      }
    }
  }
}

